{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "The closest analogue, CLR457, shares the aminopyridine-CF3 and morpholine-substituted azine core and had a brain/plasma AUC ratio of 0.07, indicating minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A related morpholine-fused heteroaromatic aminopyridine (12b) gave minimal brain exposure after oral dosing in rats.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Analogous compound 7b also showed minimal brain levels in rat PK, supporting poor CNS access for this polar morpholine/azine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Compound 22, containing a morpholine amide and CF3-pyrimidine, had a brain unbound/plasma unbound ratio of 0.08.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 8, a close CF3/morpholine analogue, had an unacceptable Bu/Pu ratio of 0.11.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A morpholine-pyridine radiotracer ([18F]21) showed good brain uptake in rats, but it lacks the triazine/CF3/amino combination and is less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "PF-06455943 showed favorable brain uptake in rodents, but its core is a different azaindole/morpholine chemotype.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "GNE-7915 is brain-penetrant in rats and NHPs, but its amide/aniline architecture is less similar to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Compound 30 showed 100% brain/plasma ratio, but its anilino-pyrimidine scaffold is only distantly related to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue (CLR457) shows minimal brain penetration (AUC ratio 0.07), and several related polar morpholine/CF3 heteroaromatics also show poor CNS exposure. The query's high TPSA, low logP, and two morpholines on a triazine further argue against meaningful access. Occasional brain-penetrant morpholine analogues are less similar and do not override the dominant poor-penetration evidence.",
  "evidence_gaps": [
    "No direct in vivo brain or CSF data for the exact query molecule.",
    "No P-glycoprotein/BCRP efflux data for the query.",
    "Human CNS exposure data are absent.",
    "Morgan similarities to the closest evidence are modest (~0.39), limiting direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

